package negocio;
import java.time.LocalDateTime;
public class ParticipanteComunidad { private long id,convocatoriaId; private Long perfilJugadorId,solicitudOrigenId; private TipoParticipanteComunidad tipo; private EstadoParticipanteComunidad estado=EstadoParticipanteComunidad.CONFIRMADO; private String descripcionPublica; private OrigenParticipanteComunidad origen; private LocalDateTime fechaConfirmacion,fechaCreacion;
 public long getId(){return id;} public void setId(long v){id=v;} public long getConvocatoriaId(){return convocatoriaId;} public void setConvocatoriaId(long v){convocatoriaId=v;} public Long getPerfilJugadorId(){return perfilJugadorId;} public void setPerfilJugadorId(Long v){perfilJugadorId=v;} public Long getSolicitudOrigenId(){return solicitudOrigenId;} public void setSolicitudOrigenId(Long v){solicitudOrigenId=v;} public TipoParticipanteComunidad getTipo(){return tipo;} public void setTipo(TipoParticipanteComunidad v){tipo=v;} public EstadoParticipanteComunidad getEstado(){return estado;} public void setEstado(EstadoParticipanteComunidad v){estado=v;} public String getDescripcionPublica(){return descripcionPublica;} public void setDescripcionPublica(String v){descripcionPublica=v;} public OrigenParticipanteComunidad getOrigen(){return origen;} public void setOrigen(OrigenParticipanteComunidad v){origen=v;} public LocalDateTime getFechaConfirmacion(){return fechaConfirmacion;} public void setFechaConfirmacion(LocalDateTime v){fechaConfirmacion=v;} public LocalDateTime getFechaCreacion(){return fechaCreacion;} public void setFechaCreacion(LocalDateTime v){fechaCreacion=v;} public void validar(){if(convocatoriaId<=0||tipo==null||estado==null||origen==null)throw new IllegalArgumentException("El participante es incompleto.");if(tipo!=TipoParticipanteComunidad.EXTERNO&&perfilJugadorId==null)throw new IllegalArgumentException("El perfil es obligatorio para participantes vinculados.");if(tipo==TipoParticipanteComunidad.EXTERNO&&perfilJugadorId!=null)throw new IllegalArgumentException("Un participante externo no debe vincular un perfil.");if(origen==OrigenParticipanteComunidad.COMUNIDAD&&solicitudOrigenId==null)throw new IllegalArgumentException("La solicitud de origen es obligatoria para participantes de Comunidad.");if(origen!=OrigenParticipanteComunidad.COMUNIDAD&&solicitudOrigenId!=null)throw new IllegalArgumentException("Solo un participante originado en Comunidad puede vincular una solicitud.");}}
